    ]
  },
  {
    "alert_id": "ALERT_003",
    "title": "Viral load monitoring frequency in pregnancy",
    "message": "Guidelines specify viral load monitoring at 3 months for pregnant women newly initiating ART. Patient's VL at 10 weeks (89 copies/mL) aligns with this schedule and confirms suppression. Guidelines also indicate repeat VL at delivery if gestation exceeds 28 weeks at the time of the 3-month VL. At 22 weeks pregnant with VL done at ~10 weeks post-initiation, a repeat VL at delivery is indicated. Additionally, guidelines state VL monitoring at 6 months after ART initiation and every 6-12 months thereafter. No clinician plan was documented today, so it is unclear if follow-up VL timing was addressed.",
    "issue_type": "monitoring_gap",
    "severity": "low",
    "recommended_action": "Schedule repeat viral load at delivery (patient will be >28 weeks). Continue routine VL monitoring at 6 months post-ART initiation and every 6-12 months thereafter.",
